// Meta Instagram Webhook Signature Verification
// Production security: Verify webhook signature to prevent unauthorized requests
// Reference: Meta Instagram Graph API security requirements
// Format: X-Hub-Signature-256: sha256=<hash>

const crypto = require('crypto');
const input = $input.item.json;
const headers = input.headers || {};
const rawBody = input.raw_body || JSON.stringify(input);

// Meta sends signature in X-Hub-Signature-256 header with format: sha256=<hash>
const signatureHeader = headers['X-Hub-Signature-256'] 
  || headers['x-hub-signature-256']
  || headers['X-Hub-Signature']
  || headers['x-hub-signature'];

// Extract hash from 'sha256=<hash>' format
let receivedSignature = null;
if (signatureHeader) {
  const match = signatureHeader.match(/sha256=(.+)/i);
  if (match) {
    receivedSignature = match[1];
  } else {
    receivedSignature = signatureHeader;
  }
}

// Use Meta App Secret (same as WhatsApp - unified Meta Business API)
const appSecret = process.env.WHATSAPP_APP_SECRET || process.env.META_APP_SECRET;

if (!receivedSignature) {
  // In development, allow webhooks without signature (for testing)
  if (process.env.NODE_ENV === 'development' || process.env.ALLOW_UNSIGNED_WEBHOOKS === 'true') {
    return {
      valid: true,
      signature_verified: false,
      warning: 'Webhook signature not verified (development mode)',
      ...input
    };
  }

  return {
    valid: false,
    error: 'Missing X-Hub-Signature-256 header',
    statusCode: 401,
    security_event: 'missing_signature'
  };
}

if (!appSecret) {
  return {
    valid: false,
    error: 'WHATSAPP_APP_SECRET or META_APP_SECRET not configured',
    statusCode: 500,
    security_event: 'config_error'
  };
}

// Meta signature: HMAC-SHA256(payload, app_secret) in hex format
const payloadString = typeof rawBody === 'string' ? rawBody : JSON.stringify(rawBody);

const expectedSignature = crypto
  .createHmac('sha256', appSecret)
  .update(payloadString)
  .digest('hex');

// Constant-time comparison (prevent timing attacks)
let isValid = false;
try {
  isValid = crypto.timingSafeEqual(
    Buffer.from(receivedSignature, 'hex'),
    Buffer.from(expectedSignature, 'hex')
  );
} catch (e) {
  isValid = false;
}

if (!isValid) {
  return {
    valid: false,
    error: 'Invalid Meta Instagram signature',
    statusCode: 401,
    security_event: 'invalid_signature'
  };
}

return {
  valid: true,
  signature_verified: true,
  ...input
};

// Parse Instagram Comment Webhook Payload
// Meta Instagram Graph API webhook format
// Reference: https://developers.facebook.com/docs/instagram-api/guides/webhooks

const payload = $input.item.json;
const entry = payload.entry || [];

if (entry.length === 0) {
  return {
    error: 'No entry in webhook payload',
    valid: false
  };
}

const firstEntry = entry[0];
const changes = firstEntry.changes || [];

if (changes.length === 0) {
  return {
    error: 'No changes in webhook payload',
    valid: false
  };
}

const change = changes[0];
const value = change.value || {};

// Extract comment data
const commentId = value.id || value.comment_id;
const commentText = value.text || '';
const mediaId = value.media?.id || value.media_id;
const mediaPermalink = value.media?.permalink || '';
const userId = value.from?.id || value.user_id;
const username = value.from?.username || '';
const timestamp = value.timestamp || Math.floor(Date.now() / 1000);

// Extract page/account ID
const pageId = firstEntry.id || payload.object_id;

return {
  valid: true,
  comment_id: commentId,
  comment_text: commentText,
  media_id: mediaId,
  media_permalink: mediaPermalink,
  instagram_user_id: userId,
  instagram_username: username,
  page_id: pageId,
  timestamp: timestamp,
  tenant_id: payload.tenant_id
};

// Keyword Detection: Identify lead intent from comment
// Keywords: DM, Price, YES, Interested, Want, Buy
// Supports English, Swahili, Sheng

const commentText = ($input.item.json.comment_text || '').toLowerCase();

// Lead intent keywords (English, Swahili, Sheng)
const leadKeywords = [
  'dm', 'direct message', 'message me',
  'price', 'cost', 'how much', 'bei', 'pesa',
  'yes', 'interested', 'want', 'taka', 'nataka',
  'buy', 'purchase', 'nunua', 'order', 'oda',
  'info', 'information', 'more', 'zaidi'
];

// Check if comment contains lead keywords
const hasLeadIntent = leadKeywords.some(keyword => 
  commentText.includes(keyword)
);

// Determine lead quality (high, medium, low)
let leadQuality = 'low';
if (['dm', 'price', 'yes', 'interested', 'buy'].some(k => commentText.includes(k))) {
  leadQuality = 'high';
} else if (['info', 'more', 'want'].some(k => commentText.includes(k))) {
  leadQuality = 'medium';
}

return {
  ...$input.item.json,
  has_lead_intent: hasLeadIntent,
  lead_quality: leadQuality
};

// Extract Phone Number from Instagram Bio
// Kenyan phone patterns: +254, 07, 254
// Reference: Kenya phone number formats

const userData = $('Fetch Instagram User Bio').first()?.json || {};
const bio = (userData.biography || '').toLowerCase();
const commentData = $input.item.json;

// Kenyan phone number regex patterns
const phonePatterns = [
  /\+254\d{9}/g,           // +254712345678
  /254\d{9}/g,            // 254712345678
  /07\d{8}/g,             // 0712345678
  /\+254\s?\d{3}\s?\d{3}\s?\d{3}/g,  // +254 712 345 678
  /0\d{2}\s?\d{3}\s?\d{3}/g          // 071 234 5678
];

let extractedPhone = null;

// Try to extract phone from bio
for (const pattern of phonePatterns) {
  const matches = bio.match(pattern);
  if (matches && matches.length > 0) {
    // Take first match and normalize
    let phone = matches[0].replace(/\s+/g, '');

    // Normalize to +254 format
    if (phone.startsWith('07')) {
      phone = '+254' + phone.substring(1);
    } else if (phone.startsWith('254') && !phone.startsWith('+254')) {
      phone = '+' + phone;
    } else if (!phone.startsWith('+')) {
      phone = '+254' + phone;
    }

    extractedPhone = phone;
    break;
  }
}

// If no phone in bio, check comment text
if (!extractedPhone) {
  const commentText = (commentData.comment_text || '').toLowerCase();
  for (const pattern of phonePatterns) {
    const matches = commentText.match(pattern);
    if (matches && matches.length > 0) {
      let phone = matches[0].replace(/\s+/g, '');
      if (phone.startsWith('07')) {
        phone = '+254' + phone.substring(1);
      } else if (phone.startsWith('254') && !phone.startsWith('+254')) {
        phone = '+' + phone;
      }
      extractedPhone = phone;
      break;
    }
  }
}

return {
  ...commentData,
  instagram_username: userData.username || commentData.instagram_username,
  bio: userData.biography || '',
  phone: extractedPhone,
  phone_extracted: extractedPhone !== null
};
